// Normalise AU Phone (+61), Email, and Spam Filter Gate
const rawText = String($input.item.json.content?.[0]?.text || '{}').slice(0, 16384).replace(/```json|```/g, '').trim();
let data;
try {
  data = JSON.parse(rawText);
} catch (err) {
  return {
    json: {
      status: 'quarantined_dlq',
      quarantined_at: new Date().toISOString(),
      enquiry_summary: 'Unknown contact',
      violations: [{ field: '__root__', message: 'Invalid JSON from model' }]
    }
  };
}

if (!data || typeof data !== 'object' || Array.isArray(data)) {
  return {
    json: {
      status: 'quarantined_dlq',
      quarantined_at: new Date().toISOString(),
      enquiry_summary: 'Unknown contact',
      violations: [{ field: '__root__', message: 'Model output must be a JSON object' }]
    }
  };
}

function cleanText(val, maxLen = 200) {
  return String(val || '')
    .replace(/[\u0000-\u001F\u007F`]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maxLen);
}

function escapeSlackMrkdwn(val, maxLen = 200) {
  return cleanText(val, maxLen)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const violations = [];
const email = String(data.contact_email || '').trim().toLowerCase();
if (email.length < 5 || email.length > 254 || !/^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,24}$/.test(email)) {
  violations.push({ field: 'contact_email', message: 'Invalid contact_email address' });
}

function normaliseAuPhone(raw) {
  if (!raw) return null;
  const digits = String(raw).slice(0, 32).replace(/[^\d+]/g, '');
  if (/^0[23478]\d{8}$/.test(digits)) return '+61' + digits.slice(1);
  if (/^\+?61[23478]\d{8}$/.test(digits)) return digits.startsWith('+') ? digits : '+' + digits;
  return null;
}

const phone = normaliseAuPhone(data.contact_phone);
if (data.contact_phone && !phone) {
  violations.push({ field: 'contact_phone', message: 'Unrecognised Australian phone format' });
}

const score = Number(data.urgency_score);
if (!Number.isInteger(score) || score < 1 || score > 10) {
  violations.push({ field: 'urgency_score', message: 'urgency_score must be integer 1..10' });
}

const ALLOWED_INTENT_TIERS = ['high_intent', 'standard', 'spam_or_solicitation'];
const intentTier = String(data.intent_tier || '').trim();
if (!ALLOWED_INTENT_TIERS.includes(intentTier)) {
  violations.push({ field: 'intent_tier', message: 'intent_tier must be high_intent, standard, or spam_or_solicitation' });
} else if (intentTier === 'spam_or_solicitation') {
  violations.push({ field: 'intent_tier', message: 'Filtered as cold spam or solicitation' });
}

const rawFullName = cleanText(data.contact_name || 'Unknown', 120);
const [firstName, ...restName] = rawFullName.split(/\s+/);
const lastName = restName.join(' ') || '-';
const rawCompany = cleanText(data.company_name, 120);

if (violations.length > 0) {
  return {
    json: {
      status: 'quarantined_dlq',
      quarantined_at: new Date().toISOString(),
      enquiry_summary: escapeSlackMrkdwn(`${rawFullName} · ${email || 'no-email'} (${rawCompany || 'Unknown company'})`, 240),
      violations
    }
  };
}

const safeSystems = Array.isArray(data.systems_mentioned)
  ? data.systems_mentioned.slice(0, 12).map(s => escapeSlackMrkdwn(s, 40)).filter(Boolean)
  : [];

return {
  json: {
    status: 'committed',
    validated_at: new Date().toISOString(),
    lead: {
      first_name: escapeSlackMrkdwn(firstName, 80),
      last_name: escapeSlackMrkdwn(lastName, 80),
      email: escapeSlackMrkdwn(email, 254),
      phone,
      company: escapeSlackMrkdwn(rawCompany, 120),
      intent_tier: intentTier,
      urgency_score: score,
      systems_mentioned: safeSystems,
      summary_one_line: escapeSlackMrkdwn(data.summary_one_line, 280),
      draft_reply: escapeSlackMrkdwn(data.draft_reply, 600)
    },
    hubspot_contact_payload: {
      properties: {
        email,
        firstname: firstName,
        lastname: lastName,
        phone: phone || '',
        company: rawCompany,
        hs_lead_status: intentTier === 'high_intent' ? 'OPEN_DEAL' : 'NEW'
      }
    }
  }
};

